package com.zhitu.controller;
import com.zhitu.common.ApiResponse;import com.zhitu.service.ResumeService;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/resumes") public class ResumeController {private final ResumeService service;public ResumeController(ResumeService s){service=s;}@PostMapping("/parse")public ApiResponse<Map<String,Object>>parse(@RequestParam MultipartFile file)throws Exception{return ApiResponse.ok("简历解析完成",service.parse(file));}@PostMapping("/parse-image")public ApiResponse<Map<String,Object>>parseImage(@RequestParam MultipartFile file)throws Exception{return ApiResponse.ok("图片简历识别完成",service.parseImage(file));}@PostMapping("/parse-text")public ApiResponse<Map<String,Object>>text(@RequestBody Map<String,String> body){return ApiResponse.ok(service.parseText(body.getOrDefault("text","")));}@GetMapping public ApiResponse<List<Map<String,Object>>>profiles(){return ApiResponse.ok(service.profiles());}}
